<?php
if (!defined('ABSPATH')) exit;
final class WPSX_Advanced {
 const OPT='wpsx_advanced'; const HOOK='wpsx_advanced_daily';
 static function defaults(){return ['two_factor'=>0,'audit'=>1,'database_audit'=>1,'scanner'=>1,'auto_core_repair'=>0,'retention'=>7,'max_files'=>15000];}
 static function cfg(){return wp_parse_args(get_option(self::OPT,[]),self::defaults());}
 static function init(){add_action('admin_menu',[__CLASS__,'menu']);add_action('admin_post_wpsx_advanced_save',[__CLASS__,'save']);add_action('admin_post_wpsx_advanced_scan',[__CLASS__,'run_scan']);add_action('admin_post_wpsx_advanced_repair',[__CLASS__,'run_repair']);add_action(self::HOOK,[__CLASS__,'daily']);add_action('admin_init',[__CLASS__,'ensure_schedule']);add_action('profile_update',[__CLASS__,'profile_change'],10,2);add_action('deleted_user',function($id){WPSX::log('user_deleted','User removed: '.(int)$id,'warning');});add_action('wp_login',function($login){if(self::cfg()['audit'])WPSX::log('login_success','Successful login: '.$login);});add_action('wp_login_failed',function($login){if(self::cfg()['audit'])WPSX::log('login_failure','Failed login for '.sanitize_user($login),'warning');});add_filter('wp_authenticate_user',[__CLASS__,'enforce_2fa'],50,2);add_action('login_form',[__CLASS__,'login_field']);add_action('show_user_profile',[__CLASS__,'profile']);add_action('edit_user_profile',[__CLASS__,'profile']);add_action('personal_options_update',[__CLASS__,'save_profile']);add_action('edit_user_profile_update',[__CLASS__,'save_profile']);}
 static function ensure_schedule(){if(!wp_next_scheduled(self::HOOK))wp_schedule_event(time()+600,'daily',self::HOOK);}
 static function menu(){add_submenu_page('wpsx','Advanced Protection','Advanced Protection','manage_options','wpsx-advanced',[__CLASS__,'page']);}
 static function profile_change($id,$old){if(self::cfg()['audit'])WPSX::log('profile','Profile changed for user '.(int)$id,'warning');}
 static function totp($secret,$step=null){$step=$step===null?floor(time()/30):$step;$key=self::base32decode($secret);if(!$key)return ''; $counter=pack('N2',0,$step);$hash=hash_hmac('sha1',$counter,$key,true);$offset=ord(substr($hash,-1))&15;$binary=(unpack('N',substr($hash,$offset,4))[1]&0x7fffffff);return str_pad((string)($binary%1000000),6,'0',STR_PAD_LEFT);}
 static function base32decode($s){$alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$bits='';foreach(str_split(strtoupper(preg_replace('/[^A-Z2-7]/i','',$s))) as $c){$n=strpos($alphabet,$c);if($n===false)return false;$bits.=str_pad(decbin($n),5,'0',STR_PAD_LEFT);} $out='';foreach(str_split($bits,8) as $b)if(strlen($b)===8)$out.=chr(bindec($b));return $out;}
 static function secret(){ $a='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$s='';for($i=0;$i<32;$i++)$s.=$a[random_int(0,31)];return $s;}
 static function login_field(){if(!self::cfg()['two_factor'])return;echo '<p><label for="wpsx_otp">Authenticator code (if enabled)<br><input type="text" inputmode="numeric" autocomplete="one-time-code" name="wpsx_otp" id="wpsx_otp" maxlength="6" class="input"></label></p>';}
 static function enforce_2fa($user,$password){if(is_wp_error($user)||!self::cfg()['two_factor'])return $user;$secret=get_user_meta($user->ID,'wpsx_totp_secret',true);if(!$secret)return $user;$otp=isset($_POST['wpsx_otp'])?preg_replace('/\D/','',wp_unslash($_POST['wpsx_otp'])):'';if(strlen($otp)!==6)return new WP_Error('wpsx_otp','Authenticator code required.');$valid=false;for($i=-1;$i<=1;$i++)if(hash_equals(self::totp($secret,floor(time()/30)+$i),$otp))$valid=true;if(!$valid)return new WP_Error('wpsx_otp','Invalid authenticator code.');return $user;}
 static function profile($user){if(get_current_user_id()!==(int)$user->ID||!current_user_can('edit_user',$user->ID))return;$secret=get_user_meta($user->ID,'wpsx_totp_pending',true);echo '<h2>Sentinel X Authenticator</h2><p>Enable global 2FA in Advanced Protection first. Use an authenticator app. Save the secret securely; no recovery codes are included in this build.</p>';wp_nonce_field('wpsx_profile','wpsx_profile_nonce');if(get_user_meta($user->ID,'wpsx_totp_secret',true)){echo '<p>Authenticator enabled. <label><input type="checkbox" name="wpsx_disable_totp" value="1"> Disable (requires your current code)</label></p><input name="wpsx_current_otp" placeholder="Current 6-digit code" maxlength="6">';}else{if(!$secret){$secret=self::secret();update_user_meta($user->ID,'wpsx_totp_pending',$secret);}echo '<p>Manual setup key: <code>'.esc_html($secret).'</code></p><p><label>Authenticator code to enable <input name="wpsx_enable_otp" maxlength="6"></label></p>';}}
 static function save_profile($id){if(get_current_user_id()!==(int)$id||!current_user_can('edit_user',$id)||empty($_POST['wpsx_profile_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['wpsx_profile_nonce'])),'wpsx_profile'))return;$otp=isset($_POST['wpsx_enable_otp'])?preg_replace('/\D/','',wp_unslash($_POST['wpsx_enable_otp'])):'';$pending=get_user_meta($id,'wpsx_totp_pending',true);if($pending&&strlen($otp)===6){foreach([-1,0,1] as $offset)if(hash_equals(self::totp($pending,floor(time()/30)+$offset),$otp)){update_user_meta($id,'wpsx_totp_secret',$pending);delete_user_meta($id,'wpsx_totp_pending');WPSX::log('two_factor','Authenticator enabled for user '.(int)$id);break;}}if(!empty($_POST['wpsx_disable_totp'])){$secret=get_user_meta($id,'wpsx_totp_secret',true);$code=isset($_POST['wpsx_current_otp'])?preg_replace('/\D/','',wp_unslash($_POST['wpsx_current_otp'])):'';if($secret&&hash_equals(self::totp($secret),$code)){delete_user_meta($id,'wpsx_totp_secret');WPSX::log('two_factor','Authenticator disabled for user '.(int)$id,'warning');}}}
 static function authorize(){if(!current_user_can('manage_options'))wp_die('Forbidden',403);check_admin_referer('wpsx_advanced');}
 static function save(){self::authorize();$c=self::cfg();foreach(['two_factor','audit','database_audit','scanner','auto_core_repair'] as $key)$c[$key]=isset($_POST[$key])?1:0;$c['retention']=max(1,min(30,(int)($_POST['retention']??7)));$c['max_files']=max(1000,min(50000,(int)($_POST['max_files']??15000)));$c['auto_core_repair']=0;update_option(self::OPT,$c,false);WPSX::log('settings','Advanced protection settings updated');self::redirect('Settings saved.');}
 static function redirect($message){set_transient('wpsx_advanced_notice_'.get_current_user_id(),$message,60);wp_safe_redirect(admin_url('admin.php?page=wpsx-advanced'));exit;}
 static function run_scan(){self::authorize();$r=self::daily();self::redirect('Scan completed. Findings: '.count($r));}
 static function run_repair(){self::authorize();$path=isset($_POST['path'])?sanitize_text_field(wp_unslash($_POST['path'])):'';$result=WPSX::repair($path);self::redirect(is_wp_error($result)?$result->get_error_message():'Verified core file restored.');}
 static function daily(){if(!self::cfg()['scanner'])return []; $findings=self::scan_files();if(self::cfg()['database_audit'])self::database_audit();/* Automatic repairs require verified staging integration tests. */update_option('wpsx_advanced_findings',$findings,false);update_option('wpsx_advanced_last_scan',time(),false);if($findings)WPSX::log('scanner',count($findings).' findings need review','critical');return $findings;}
 static function scan_files(){ $results=[];$checks=WPSX::core_files();if(!is_wp_error($checks)){foreach($checks as $path=>$md5){$full=ABSPATH.$path;if(!is_file($full)||!hash_equals(strtolower($md5),strtolower((string)@md5_file($full))))$results[]=['path'=>$path,'type'=>'core_mismatch','detail'=>'Official checksum mismatch'];}}$dirs=[WP_CONTENT_DIR.'/uploads',WP_CONTENT_DIR.'/mu-plugins',WP_CONTENT_DIR.'/plugins',WP_CONTENT_DIR.'/themes'];$count=0;$max=self::cfg()['max_files'];foreach($dirs as $dir){if(!is_dir($dir))continue;try{$iterator=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir,FilesystemIterator::SKIP_DOTS));foreach($iterator as $file){if(++$count>$max)break 2;if(!$file->isFile()||$file->isLink()||$file->getSize()>2*1024*1024)continue;$path=$file->getPathname();$relative=str_replace(ABSPATH,'',$path);if(strpos($path,WP_CONTENT_DIR.'/wpsx-private/')===0)continue;if(preg_match('~/(?:uploads|cache)/.*\.(?:php[0-9]?|phtml|phar)$~i',$path))$results[]=['path'=>$relative,'type'=>'executable_in_uploads','detail'=>'Executable code in user-writable directory'];if(!preg_match('/\.(php|phtml|phar)$/i',$path))continue;$body=@file_get_contents($path,false,null,0,262144);if(!is_string($body))continue;$signals=[];if(preg_match('/\beval\s*\(\s*(?:base64_decode|gzinflate|str_rot13)\s*\(/i',$body))$signals[]='obfuscated evaluation';if(preg_match('/\b(?:shell_exec|passthru|system)\s*\(\s*\$_(?:GET|POST|REQUEST)/i',$body))$signals[]='request-driven shell execution';if(preg_match('/\b(?:file_put_contents|fwrite)\s*\([^;]{0,150}\$_(?:GET|POST|REQUEST)/is',$body))$signals[]='request-driven file writing';if($signals)$results[]=['path'=>$relative,'type'=>'heuristic','detail'=>implode(', ',$signals)];}}catch(Throwable $e){WPSX::log('scanner_error',$e->getMessage(),'warning');}}return array_slice($results,0,500);}
 static function database_audit(){global $wpdb;$admins=get_users(['role'=>'administrator','fields'=>['ID','user_login','user_registered']]);$snapshot=[];foreach($admins as $u)$snapshot[]=$u->ID.':'.$u->user_login;sort($snapshot);$prior=get_option('wpsx_admin_snapshot',null);if(is_array($prior)&&$prior!==$snapshot)WPSX::log('admin_change','Administrator account list changed','critical');update_option('wpsx_admin_snapshot',$snapshot,false);$registration=(int)get_option('users_can_register');$role=get_option('default_role');if($registration&&$role==='administrator')WPSX::log('database','Public registration grants administrator role','critical');}
 static function page(){if(!current_user_can('manage_options'))return;$c=self::cfg();$items=get_option('wpsx_advanced_findings',[]);echo '<div class="wrap"><h1>WP Sentinel X — Advanced Protection</h1><p>Heuristic results may be false positives. Automatic quarantine is intentionally disabled for unknown code. WordPress cron is traffic-dependent; server-level rules and offsite backups require separate infrastructure.</p>';$notice=get_transient('wpsx_advanced_notice_'.get_current_user_id());if($notice){echo '<div class="notice notice-info"><p>'.esc_html($notice).'</p></div>';delete_transient('wpsx_advanced_notice_'.get_current_user_id());}echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="wpsx_advanced_save">';wp_nonce_field('wpsx_advanced');echo '<table class="form-table">';$labels=['two_factor'=>'Require TOTP for enrolled accounts (enroll from user profile)','audit'=>'Audit login and profile activity','database_audit'=>'Audit administrator accounts and dangerous registration settings','scanner'=>'Daily malware heuristics and core verification','auto_core_repair'=>'Automatic core repair unavailable until staging validation'];foreach($labels as $key=>$label)echo '<tr><th>'.esc_html($label).'</th><td><input type="checkbox" name="'.esc_attr($key).'" '.checked(!empty($c[$key]),true,false).'></td></tr>';echo '<tr><th>Maximum files per scan</th><td><input type="number" name="max_files" min="1000" max="50000" value="'.esc_attr($c['max_files']).'"></td></tr></table>';submit_button('Save advanced settings');echo '</form><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('wpsx_advanced');echo '<input type="hidden" name="action" value="wpsx_advanced_scan">';submit_button('Run advanced scan','secondary');echo '</form><h2>Findings</h2><p>Last scan: '.esc_html(($t=get_option('wpsx_advanced_last_scan'))?wp_date('Y-m-d H:i',$t):'Never').'</p><table class="widefat striped"><thead><tr><th>File</th><th>Finding</th><th>Detail</th><th>Action</th></tr></thead><tbody>';foreach(array_slice($items,0,100) as $item){echo '<tr><td><code>'.esc_html($item['path']).'</code></td><td>'.esc_html($item['type']).'</td><td>'.esc_html($item['detail']).'</td><td>';if($item['type']==='core_mismatch'){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('wpsx_advanced');echo '<input type="hidden" name="action" value="wpsx_advanced_repair"><input type="hidden" name="path" value="'.esc_attr($item['path']).'">';submit_button('Restore verified core','small','submit',false);echo '</form>';}echo '</td></tr>';}if(!$items)echo '<tr><td colspan="4">No findings recorded; this is not proof the site is clean.</td></tr>';echo '</tbody></table></div>';}
}
WPSX_Advanced::init();
